using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed the discriminator property
        // from "Discriminator" to "$type". Existing documents still use the
        // old name, so we must explicitly preserve it.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 changed the default id format from
        // "Discriminator|Key" (e.g. "Blog|1") to just "Key". To read
        // existing documents we must opt back in to the legacy format.
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);
        modelBuilder.Entity<Blog>().Property(e => e.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().UseIdProperty(
            idProperty: "__id",
            jsonIdProperty: "id");

        // Breaking change 3: HasIndex() is no longer silently ignored on the
        // Cosmos provider — it now throws. Cosmos has no secondary-index
        // support in EF Core, so the call must be removed.
        // (removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        base.OnConfiguring(options);
        // Breaking change 4: Synchronous I/O now throws by default on the
        // Cosmos provider. If async migration isn't feasible everywhere yet,
        // enable the compatibility switch. Prefer converting to async instead.
        // options.UseCosmos(...).EnableSyncApiSupport();
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

